/* === The Metropolitan Herald - Styles === */

:root {
    --color-primary: #0056b3;
    --color-primary-dark: #003d80;
    --color-secondary: #e63946;
    --color-text: #1a1a1a;
    --color-text-light: #666;
    --color-bg: #ffffff;
    --color-bg-alt: #f8f9fa;
    --color-border: #dee2e6;
    --font-heading: 'Georgia', serif;
    --font-body: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 2rem;
    --spacing-xl: 4rem;
    --max-width: 1200px;
    --focus-outline: 3px solid #ffbf47;
}

/* === Reset & Base === */
*, *::before, *::after {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: var(--font-body);
    color: var(--color-text);
    background-color: var(--color-bg);
    line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    margin-top: 0;
    line-height: 1.2;
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color 0.2s ease;
}

a:hover {
    color: var(--color-primary-dark);
    text-decoration: underline;
}

a:focus-visible, button:focus-visible, input:focus-visible {
    outline: var(--focus-outline);
    outline-offset: 2px;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

/* === Layout === */
.container {
    width: 100%;
    max-width: var(--max-width);
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

.grid {
    display: grid;
    gap: var(--spacing-lg);
}

.grid-2 {
    grid-template-columns: 1fr;
}

.grid-3 {
    grid-template-columns: 1fr;
}

@media (min-width: 768px) {
    .grid-2 {
        grid-template-columns: repeat(2, 1fr);
    }
    .grid-3 {
        grid-template-columns: repeat(3, 1fr);
    }
}

/* === Skip Link === */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: white;
    padding: var(--spacing-sm) var(--spacing-md);
    z-index: 1000;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* === Header & Nav === */
.site-header {
    background-color: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-md) 0;
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-inner {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--color-text);
    text-decoration: none;
}

.logo:hover {
    text-decoration: none;
}

.nav-toggle {
    display: block;
    background: none;
    border: 1px solid var(--color-border);
    padding: var(--spacing-sm);
    cursor: pointer;
    border-radius: 4px;
}

.nav-toggle:hover {
    background-color: var(--color-bg-alt);
}

.primary-nav {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background-color: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    padding: var(--spacing-md);
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.primary-nav.is-open {
    display: block;
}

.nav-list {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

@media (min-width: 768px) {
    .nav-toggle {
        display: none;
    }
    .primary-nav {
        display: block !important;
        position: static;
        border: none;
        box-shadow: none;
        padding: 0;
    }
    .nav-list {
        flex-direction: row;
        gap: var(--spacing-lg);
    }
}

.nav-link {
    font-weight: 500;
    color: var(--color-text);
}

.nav-link[aria-current="page"] {
    color: var(--color-primary);
    border-bottom: 2px solid var(--color-primary);
}

/* === Hero Section === */
.hero-section {
    padding: var(--spacing-xl) 0;
    background-color: var(--color-bg-alt);
}

.hero-grid {
    display: grid;
    gap: var(--spacing-lg);
}

@media (min-width: 768px) {
    .hero-grid {
        grid-template-columns: 2fr 1fr;
    }
}

.hero-main {
    position: relative;
}

.hero-image {
    width: 100%;
    height: 300px;
    background-color: #ccc;
    object-fit: cover;
    border-radius: 4px;
}

.hero-content {
    margin-top: var(--spacing-md);
}

.hero-title {
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
}

.hero-summary {
    color: var(--color-text-light);
    font-size: 1.1rem;
}

.hero-side {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
}

.side-story {
    border-bottom: 1px solid var(--color-border);
    padding-bottom: var(--spacing-md);
}

.side-story:last-child {
    border-bottom: none;
}

.side-story h3 {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-xs);
}

/* === Article Grid === */
.article-grid {
    display: grid;
    gap: var(--spacing-lg);
}

@media (min-width: 768px) {
    .article-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}

.article-card {
    border: 1px solid var(--color-border);
    border-radius: 4px;
    overflow: hidden;
    transition: box-shadow 0.2s ease;
}

.article-card:hover {
    box-shadow: 0 4px 8px rgba(0,0,0,0.1);
}

.article-image {
    width: 100%;
    height: 200px;
    background-color: #eee;
    object-fit: cover;
}

.article-body {
    padding: var(--spacing-md);
}

.article-category {
    font-size: 0.8rem;
    text-transform: uppercase;
    color: var(--color-primary);
    font-weight: bold;
    margin-bottom: var(--spacing-xs);
}

.article-title {
    font-size: 1.2rem;
    margin-bottom: var(--spacing-sm);
}

.article-excerpt {
    color: var(--color-text-light);
    font-size: 0.95rem;
    margin-bottom: var(--spacing-sm);
}

.article-meta {
    font-size: 0.8rem;
    color: var(--color-text-light);
}

/* === Sidebar === */
.sidebar {
    background-color: var(--color-bg-alt);
    padding: var(--spacing-lg);
    border-radius: 4px;
}

.sidebar h3 {
    border-bottom: 2px solid var(--color-primary);
    padding-bottom: var(--spacing-sm);
    margin-bottom: var(--spacing-md);
}

.trending-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.trending-item {
    margin-bottom: var(--spacing-md);
    padding-bottom: var(--spacing-md);
    border-bottom: 1px solid var(--color-border);
}

.trending-item:last-child {
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}

.trending-number {
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--color-secondary);
    margin-right: var(--spacing-sm);
}

.trending-title {
    font-weight: 500;
}

/* === Newsletter === */
.newsletter-section {
    background-color: var(--color-primary);
    color: white;
    padding: var(--spacing-xl) 0;
    text-align: center;
}

.newsletter-section h2 {
    color: white;
}

.newsletter-form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    max-width: 500px;
    margin: var(--spacing-md) auto 0;
}

@media (min-width: 768px) {
    .newsletter-form {
        flex-direction: row;
    }
}

.newsletter-input {
    flex: 1;
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: 4px;
    font-size: 1rem;
}

.newsletter-btn {
    padding: var(--spacing-sm) var(--spacing-lg);
    background-color: var(--color-secondary);
    color: white;
    border: none;
    border-radius: 4px;
    font-weight: bold;
    cursor: pointer;
    transition: background-color 0.2s;
}

.newsletter-btn:hover {
    background-color: #c92a35;
}

.newsletter-message {
    margin-top: var(--spacing-sm);
    font-size: 0.9rem;
}

/* === Footer === */
.site-footer {
    background-color: #1a1a1a;
    color: #ccc;
    padding: var(--spacing-xl) 0 var(--spacing-lg);
}

.footer-grid {
    display: grid;
    gap: var(--spacing-lg);
}

@media (min-width: 768px) {
    .footer-grid {
        grid-template-columns: repeat(4, 1fr);
    }
}

.footer-col h4 {
    color: white;
    margin-bottom: var(--spacing-md);
}

.footer-links {
    list-style: none;
    padding: 0;
    margin: 0;
}

.footer-links li {
    margin-bottom: var(--spacing-sm);
}

.footer-links a {
    color: #ccc;
}

.footer-links a:hover {
    color: white;
}

.footer-bottom {
    margin-top: var(--spacing-xl);
    padding-top: var(--spacing-lg);
    border-top: 1px solid #333;
    text-align: center;
    font-size: 0.9rem;
