}

/* === Premium Gate === */
.premium-overlay {
    position: relative;
    overflow: hidden;
}

.premium-overlay::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 50%;
    background: linear-gradient(to top, rgba(255,255,255,1) 10%, rgba(255,255,255,0) 100%);
