/* === The Metropolitan Herald - Styles === */

:root {
    --color-primary: #0056b3;
    --color-primary-dark: #003d80;
    --color-secondary: #c92a35;
    --color-text: #1a1a1a;
    --color-text-light: #666;
    --color-bg: #ffffff;
    --color-bg-alt: #f8f9fa;
    --color-border: #dee2e6;
