        grid-template-columns: repeat(3, 1fr);
    }
}

.article-card {
    border: 1px solid var(--color-border);
    border-radius: 4px;
    overflow: hidden;
    transition: box-shadow 0.2s ease;
}

.article-card:hover {
    box-shadow: 0 4px 8px rgba(0,0,0,0.1);
}

.article-image {
    width: 100%;
